#!/usr/bin/env bash
# recipes/crate-wasm-bindgen-shared--0-2-90/build.sh -- stage the wasm-bindgen-shared 0.2.90 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/wasm-bindgen-shared-0.2.90"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"4d91413b1c31d7539ba5ef2451af3f0b833a005eb27a631cec32bc0635a8602b"}\n' > "${dest}/.cargo-checksum.json"
